def transform(grid):
    out = [row[:] for row in grid]
    bg = grid[1][1]
    b = [[grid[r][7 + c] for c in range(5)] for r in range(1, 6)]
    c = [[grid[r][13 + c] for c in range(5)] for r in range(1, 6)]
    nb = sum(v != bg for row in b for v in row)
    nc = sum(v != bg for row in c for v in row)
    base, secondary = (b, c) if nb >= nc else (c, b)
    result = [row[:] for row in base]

    # Add secondary components lying in the lower/right half.  Components
    # cut by the base are considered separately.
    seen = set()
    for r in range(5):
        for col in range(5):
            if secondary[r][col] == bg or base[r][col] != bg or (r, col) in seen:
                continue
            stack = [(r, col)]
            seen.add((r, col))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < 5 and 0 <= xx < 5 and (yy, xx) not in seen:
                        if secondary[yy][xx] != bg and base[yy][xx] == bg:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            if sum(y + x for y, x in comp) > 4 * len(comp):
                for y, x in comp:
                    result[y][x] = secondary[y][x]

    for r in range(5):
        for col in range(5):
            out[r + 1][19 + col] = result[r][col]
    return out
